unsafe extern "C" fn load_histogram(
    mut database: *mut sqlite3,
    mut query: *const investigation_search_query_t,
    mut summary: *mut investigation_search_summary_t,
) -> ::core::ffi::c_int {
    let mut range: int64_t =
        (*query).end_time as int64_t - (*query).start_time as int64_t + 1 as int64_t;
    let mut bucket_seconds: ::core::ffi::c_int =
        ((range + INVESTIGATION_SEARCH_MAX_HISTOGRAM_BUCKETS as int64_t - 1 as int64_t)
            / INVESTIGATION_SEARCH_MAX_HISTOGRAM_BUCKETS as int64_t) as ::core::ffi::c_int;
    if bucket_seconds < 1 as ::core::ffi::c_int {
        bucket_seconds = 1 as ::core::ffi::c_int;
    }
    (*summary).histogram_bucket_seconds = bucket_seconds;
    let mut statement: *mut sqlite3_stmt = ::core::ptr::null_mut::<sqlite3_stmt>();
    let mut next_parameter: ::core::ffi::c_int = prepare_with_where(
        database,
        b"SELECT CASE WHEN d.timestamp < ? THEN 0 ELSE CAST((d.timestamp - ?) / ? AS INTEGER) END AS bucket, COUNT(*), MIN(CASE WHEN d.timestamp < ? THEN ? ELSE d.timestamp END) FROM detections d\0"
            .as_ptr() as *const ::core::ffi::c_char,
        query,
        r#false != 0,
        r#true != 0,
        b" GROUP BY bucket ORDER BY bucket ASC;\0".as_ptr()
            as *const ::core::ffi::c_char,
        6 as ::core::ffi::c_int,
        &raw mut statement,
    );
    if next_parameter < 0 as ::core::ffi::c_int {
        return -1 as ::core::ffi::c_int;
    }
    sqlite3_bind_int64(
        statement,
        1 as ::core::ffi::c_int,
        (*query).start_time as sqlite3_int64,
    );
    sqlite3_bind_int64(
        statement,
        2 as ::core::ffi::c_int,
        (*query).start_time as sqlite3_int64,
    );
    sqlite3_bind_int(statement, 3 as ::core::ffi::c_int, bucket_seconds);
    sqlite3_bind_int64(
        statement,
        4 as ::core::ffi::c_int,
        (*query).start_time as sqlite3_int64,
    );
    sqlite3_bind_int64(
        statement,
        5 as ::core::ffi::c_int,
        (*query).start_time as sqlite3_int64,
    );
    let mut count: ::core::ffi::c_int = 0 as ::core::ffi::c_int;
    let mut step: ::core::ffi::c_int = 0;
    loop {
        step = sqlite3_step(statement);
        if !(step == SQLITE_ROW && count < INVESTIGATION_SEARCH_MAX_HISTOGRAM_BUCKETS) {
            break;
        }
        let mut bucket: int64_t =
            sqlite3_column_int64(statement, 0 as ::core::ffi::c_int) as int64_t;
        let mut bucket_start: time_t =
            (*query).start_time + (bucket * bucket_seconds as int64_t) as time_t;
        let c2rust_fresh32 = count;
        count += 1;
        let mut output: *mut investigation_search_histogram_bucket_t =
            (&raw mut (*summary).histogram as *mut investigation_search_histogram_bucket_t)
                .offset(c2rust_fresh32 as isize);
        (*output).start_time = bucket_start;
        (*output).end_time = bucket_start + bucket_seconds as time_t;
        if (*output).end_time > (*query).end_time {
            (*output).end_time = (*query).end_time;
        }
        (*output).event_time = sqlite3_column_int64(statement, 2 as ::core::ffi::c_int) as time_t;
        (*output).count = sqlite3_column_int64(statement, 1 as ::core::ffi::c_int) as int64_t;
    }
    sqlite3_finalize(statement);
    (*summary).histogram_count = count;
    return if step == SQLITE_DONE {
        0 as ::core::ffi::c_int
    } else {
        -1 as ::core::ffi::c_int
    };
}
unsafe extern "C" fn load_spatial_coverage(
    mut database: *mut sqlite3,
    mut query: *const investigation_search_query_t,
    mut summary: *mut investigation_search_summary_t,
) -> ::core::ffi::c_int {
    if !(*query).has_region {
        return 0 as ::core::ffi::c_int;
    }
    let mut statement: *mut sqlite3_stmt = ::core::ptr::null_mut::<sqlite3_stmt>();
    if prepare_with_where(
        database,
        b"SELECT COUNT(*), COALESCE(SUM(CASE WHEN d.x IS NOT NULL AND d.y IS NOT NULL AND d.width IS NOT NULL AND d.height IS NOT NULL AND d.x >= 0 AND d.y >= 0 AND d.width > 0 AND d.height > 0 AND d.x + d.width <= 1 AND d.y + d.height <= 1 THEN 1 ELSE 0 END), 0) FROM detections d\0"
            .as_ptr() as *const ::core::ffi::c_char,
        query,
        r#false != 0,
        r#false != 0,
        b";\0".as_ptr() as *const ::core::ffi::c_char,
        1 as ::core::ffi::c_int,
        &raw mut statement,
    ) < 0 as ::core::ffi::c_int
    {
        return -1 as ::core::ffi::c_int;
    }
    let mut step: ::core::ffi::c_int = sqlite3_step(statement);
    if step == SQLITE_ROW {
        let mut scoped_rows: int64_t =
            sqlite3_column_int64(statement, 0 as ::core::ffi::c_int) as int64_t;
        (*summary).spatial_metadata_rows =
            sqlite3_column_int64(statement, 1 as ::core::ffi::c_int) as int64_t;
        (*summary).spatial_missing_rows = scoped_rows - (*summary).spatial_metadata_rows;
    }
    sqlite3_finalize(statement);
    return if step == SQLITE_ROW {
        0 as ::core::ffi::c_int
    } else {
        -1 as ::core::ffi::c_int
    };
}
